import {
  ClickableMonarchDevice,
  getLocalSolvedPuzzleMap,
  PuzzleInfoBox,
} from "@hunt/puzzle-components";

const CAPSTONE_SLUG = "bird_nation";

const PuzzleComponent = () => {
  const solvedPuzzles = getLocalSolvedPuzzleMap();

  return CAPSTONE_SLUG in solvedPuzzles ? (
    <div className="flex items-center gap-2">
      The Aviaria Puzzmon invite you to journal with them in their natural
      habitat.
      <ClickableMonarchDevice zoneSlug="aviaria" className="w-20" />
    </div>
  ) : (
    <PuzzleInfoBox copyable={false}>
      You need to solve the{" "}
      <a href={`/puzzles/${CAPSTONE_SLUG}`}>Aviaria capstone puzzle</a> before
      you can access this task.
    </PuzzleInfoBox>
  );
};

export default PuzzleComponent;
